let joining: Int32Array | undefined;

/** The index of the range holding `codePoint` in the 3-wide table, or -1. */
function findJoining(codePoint: number): number {
  joining ??= Int32Array.from(joiningData());
  let low = 0;
  let high = joining.length / 3 - 1;
  while (low <= high) {
    const middle = (low + high) >> 1;
    const at = middle * 3;
    if (codePoint < (joining[at] as number)) high = middle - 1;
    else if (codePoint > (joining[at + 1] as number)) low = middle + 1;
    else return at;
  }
  return -1;
}

/** The Joining_Type of `codePoint`. */
export function joiningType(codePoint: number): JoiningType {
  const at = findJoining(codePoint);
  return at === -1 ? 'U' : (NAMES[(joining as Int32Array)[at + 2] as number] as JoiningType);
}
